create table if not exists public.financial_transfers(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.tenants(id) on delete cascade,source_account_id uuid not null references public.financial_accounts(id),destination_account_id uuid not null references public.financial_accounts(id),amount numeric(18,2) not null check(amount>0),reference text,description text,created_by uuid not null default auth.uid(),created_at timestamptz not null default now(),check(source_account_id<>destination_account_id));
create index if not exists financial_transfers_tenant_date_idx on public.financial_transfers(tenant_id,created_at desc);
alter table public.financial_transfers enable row level security;
drop policy if exists financial_transfers_read on public.financial_transfers;
create policy financial_transfers_read on public.financial_transfers for select to authenticated using(tenant_id=(select public.current_tenant_id()));
drop policy if exists financial_transfers_insert on public.financial_transfers;
create policy financial_transfers_insert on public.financial_transfers for insert to authenticated with check(tenant_id=(select public.current_tenant_id()) and created_by=(select auth.uid()) and public.has_tenant_role(array['owner','admin','manager','cashier','accountant']));
grant select,insert on public.financial_transfers to authenticated;
create or replace function public.apply_financial_transfer() returns trigger language plpgsql security definer set search_path='' as $$ declare v_tenant uuid; v_source uuid; v_dest uuid; begin if auth.uid() is null then raise exception 'Authentication required' using errcode='42501'; end if; v_tenant:=public.current_tenant_id(); if v_tenant is null or new.tenant_id<>v_tenant or new.created_by<>auth.uid() then raise exception 'Tenant or creator mismatch' using errcode='42501'; end if; if not public.has_tenant_role(array['owner','admin','manager','cashier','accountant']) then raise exception 'Insufficient permission' using errcode='42501'; end if; if new.source_account_id=new.destination_account_id then raise exception 'Source and destination must differ'; end if; perform 1 from public.financial_accounts where tenant_id=v_tenant and id in(new.source_account_id,new.destination_account_id) and is_active order by id for update; select id into v_source from public.financial_accounts where id=new.source_account_id and tenant_id=v_tenant and is_active; select id into v_dest from public.financial_accounts where id=new.destination_account_id and tenant_id=v_tenant and is_active; if v_source is null or v_dest is null then raise exception 'One or both accounts are unavailable'; end if; insert into public.financial_transactions(tenant_id,account_id,transaction_type,amount,balance_after,reference,description,created_by) values(v_tenant,new.source_account_id,'withdrawal',new.amount,new.amount,new.reference,coalesce(new.description,'Virement sortant'),auth.uid()); insert into public.financial_transactions(tenant_id,account_id,transaction_type,amount,balance_after,reference,description,created_by) values(v_tenant,new.destination_account_id,'deposit',new.amount,new.amount,new.reference,coalesce(new.description,'Virement entrant'),auth.uid()); return new; end; $$;
revoke all on function public.apply_financial_transfer() from public,anon,authenticated;
drop trigger if exists financial_transfer_apply on public.financial_transfers;
create trigger financial_transfer_apply after insert on public.financial_transfers for each row execute function public.apply_financial_transfer();